package com.bank.schedule;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class ScheduleEnumerator {

    private static final Logger log = Logger.getLogger(ScheduleEnumerator.class.getName());

    public List<List<Integer>> permuteUnique(int[] jobs) {
        Arrays.sort(jobs);                             // group equal jobs
        List<List<Integer>> result = new ArrayList<>();
        backtrack(jobs, new boolean[jobs.length], new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " distinct schedules");
        return result;
    }

    private void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue; // canonical order
            used[i] = true; path.add(nums[i]);
            backtrack(nums, used, path, result);
            path.remove(path.size() - 1); used[i] = false;
        }
    }
}
