package com.bank.schedule;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PermutationsIIDemo {

    private static final Logger log = Logger.getLogger(PermutationsIIDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Distinct Schedule Enumerator (Permutations II)");
        int[] jobs = {1, 1, 2}; // two identical type-1 jobs
        ScheduleEnumerator e = new ScheduleEnumerator();
        e.permuteUnique(jobs).forEach(s -> log.info("Schedule: " + s));
    }
}
